import{_ as t,o as s,c as e,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"11. 数据类型和变量","description":"The Little Book of C 中文版 — 11. 数据类型和变量","frontmatter":{"title":"11. 数据类型和变量","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","02-语言基础","中文"],"description":"The Little Book of C 中文版 — 11. 数据类型和变量","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":11,"sidebarWeight":11,"alternateZh":"/posts/c教程/zh-CN/02-语言基础/011-Data Types and Variables","alternateEn":"/posts/c教程/en-US/02-Language Basics/011-Data Types and Variables"},"headers":[],"relativePath":"posts/c教程/zh-CN/02-语言基础/011-Data Types and Variables.md","filePath":"posts/c教程/zh-CN/02-语言基础/011-Data Types and Variables.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/02-语言基础/011-Data Types and Variables.md"};function p(d,a,o,l,c,h){return s(),e("div",null,[...a[0]||(a[0]=[n(`<p>[English version](/posts/c教程/en-US/02-Language Basics/011-Data Types and Variables)</p><p>在 C 中，一切都从类型开始。类型告诉编译器要保留多少内存、如何解释存储在那里的位以及允许进行哪些操作。理解类型是编写安全高效的 C 程序的基础，它是您如何准确地说计算机的母语的基础。</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int age = 25;              // integer</span></span>
<span class="line"><span>    float height = 1.75;       // floating-point number</span></span>
<span class="line"><span>    char initial = &#39;A&#39;;        // single character</span></span>
<span class="line"><span>    double weight = 68.4;      // double-precision number</span></span>
<span class="line"><span>    printf(&quot;Age: %d\\n&quot;, age);</span></span>
<span class="line"><span>    printf(&quot;Height: %.2f\\n&quot;, height);</span></span>
<span class="line"><span>    printf(&quot;Initial: %c\\n&quot;, initial);</span></span>
<span class="line"><span>    printf(&quot;Weight: %.1lf\\n&quot;, weight);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Age: 25</span></span>
<span class="line"><span>Height: 1.75</span></span>
<span class="line"><span>Initial: A</span></span>
<span class="line"><span>Weight: 68.4</span></span></code></pre></div><h4 id="核心内置类型" tabindex="-1">核心内置类型 <a class="header-anchor" href="#核心内置类型" aria-label="Permalink to &quot;核心内置类型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>尺寸（典型）</th><th>描述</th><th>格式说明符</th></tr></thead><tbody><tr><td><code>char</code></td><td>1 字节</td><td>单个字符</td><td><code>%c</code></td></tr><tr><td><code>int</code></td><td>4 字节</td><td>整数</td><td><code>%d</code></td></tr><tr><td><code>float</code></td><td>4 字节</td><td>十进制数（单精度）</td><td><code>%f</code></td></tr><tr><td><code>double</code></td><td>8 字节</td><td>十进制数（双精度）</td><td><code>%lf</code></td></tr><tr><td><code>void</code></td><td>–</td><td>无值或类型</td><td>–</td></tr></tbody></table><p>大小可能会根据系统和编译器的不同而有所不同，但关系保持一致。</p><p>您还可以使用修饰符控制数字的行为方式：</p><table tabindex="0"><thead><tr><th>修改器</th><th>示例</th><th>意义</th></tr></thead><tbody><tr><td><code>short</code></td><td><code>short int x;</code></td><td>较小的整数（通常为 2 个字节）</td></tr><tr><td><code>long</code></td><td><code>long int y;</code></td><td>更大的整数（通常是 8 个字节）</td></tr><tr><td><code>unsigned</code></td><td><code>unsigned int z;</code></td><td>仅非负值</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unsigned int score = 100;</span></span>
<span class="line"><span>long long big_number = 1234567890123LL;</span></span></code></pre></div><h4 id="声明和初始化变量" tabindex="-1">声明和初始化变量 <a class="header-anchor" href="#声明和初始化变量" aria-label="Permalink to &quot;声明和初始化变量&quot;">​</a></h4><p>变量只是一段命名的内存。您可以通过指定其类型和名称来声明它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int count;       // declaration</span></span>
<span class="line"><span>count = 5;       // assignment</span></span></code></pre></div><p>或者两者一起：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int count = 5;   // initialization</span></span></code></pre></div><p>多重声明：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 1, y = 2, z = 3;</span></span></code></pre></div><p>变量必须在使用之前声明，并且它们的类型不能改变。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>C 是一种静态类型语言，这意味着每个变量的类型在编译时都是已知的。这使得程序更快、更安全，因为编译器可以：</p><ul><li>及早发现类型不匹配</li><li>优化内存布局</li><li>预测存储和对齐</li></ul><p>当您了解数据类型时，您就会了解代码如何直接映射到机器的内存。</p><p>C 迫使你仔细思考你正在使用什么类型的数据，这项技能可以改进你用任何语言编写的每个程序。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>创建一个存储和打印的程序：</p><ul><li>您的年龄<code>int</code></li><li>您的身高<code>float</code></li><li>你名字的第一个字母<code>char</code></li></ul><p>将两个整数相加并打印结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int a = 10, b = 20;</span></span>
<span class="line"><span>printf(&quot;Sum: %d\\n&quot;, a + b);</span></span></code></pre></div><p>尝试使用<code>unsigned int</code>并打印如果分配负值会发生什么。</p><p>使用<code>sizeof()</code>检查每种类型在系统上的大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Size of int: %zu bytes\\n&quot;, sizeof(int));</span></span></code></pre></div><p>C 中的每个数字、字符和指针都从这里开始，在类型和变量的精确世界中。一旦你熟练掌握了这些，内存布局、结构和指针就会变得非常有意义。</p>`,35)])])}const g=t(i,[["render",p]]);export{u as __pageData,g as default};
